    #[test]
    fn type_chart_matches_showdown() {
        for a in Type::ALL {
            for d in Type::ALL {
                assert_eq!(a.against(d), SHOWDOWN[a as usize][d as usize], "{a:?} vs {d:?}");
            }
        }
    }
